441	+// currencyInfo describes how a currency's minor units are written.
442	+type currencyInfo struct {
443	+	Code     string
444	+	Exponent int // number of minor-unit digits, e.g. 2 for USD
445	+}
446	+
447	+var currencies = map[string]currencyInfo{}
448	+
449	+func init() {
450	+	for _, c := range []currencyInfo{
451	+		{Code: "USD", Exponent: 2},
452	+		{Code: "EUR", Exponent: 2},
453	+		{Code: "GBP", Exponent: 2},
454	+		{Code: "CAD", Exponent: 2},
455	+		{Code: "JPY", Exponent: 0},
456	+		{Code: "KWD", Exponent: 3},
457	+	} {
458	+		currencies[c.Code] = c
459	+	}
460	+}
461	+
462	+// FormatAmount renders an amount in minor units as a decimal string for
463	+// display, e.g. 12345 USD -> "123.45" and 500 JPY -> "500".
464	+func FormatAmount(minor int64, currency string) string {
465	+	info, ok := currencies[currency]
466	+	if !ok || info.Exponent == 0 {
467	+		return strconv.FormatInt(minor, 10)
468	+	}
469	+	sign := ""
470	+	if minor < 0 {
471	+		sign, minor = "-", -minor
472	+	}
473	+	scale := int64(1)
474	+	for i := 0; i < info.Exponent; i++ {
475	+		scale *= 10
476	+	}
477	+	return fmt.Sprintf("%s%d.%0*d", sign, minor/scale, info.Exponent, minor%scale)
478	+}
