637	+func (c *PayoutClient) Send(ctx context.Context, p PayoutRequest) (PayoutResult, error) {
638	+	body, err := json.Marshal(providerPayout{
639	+		AmountMinor: int32(p.AmountCents),
640	+		Currency:    p.Currency,
641	+		Destination: p.Destination,
642	+		Reference:   p.Reference,
643	+	})
644	+	if err != nil {
645	+		return PayoutResult{}, err
646	+	}
647	+
648	+	for attempt := 1; attempt <= c.maxAttempts; attempt++ {
649	+		resp, err := c.post(ctx, body, p.Reference)
650	+		if err == nil && !retryableStatus(resp.StatusCode) {
651	+			return readPayout(resp)
652	+		}
653	+		if err == nil {
654	+			err = fmt.Errorf("payout provider: status %d", resp.StatusCode)
655	+		}
656	+		log.Printf("payout %s: attempt %d/%d: %v", p.Reference, attempt, c.maxAttempts, err)
657	+
658	+		if attempt < c.maxAttempts {
659	+			select {
660	+			case <-time.After(retryDelay(resp, c.backoff<<(attempt-1))):
661	+			case <-ctx.Done():
662	+				return PayoutResult{}, ctx.Err()
663	+			}
664	+		}
665	+		if resp != nil {
666	+			resp.Body.Close()
667	+		}
668	+	}
